  const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit' })
    .formatToParts(new Date()).map((x) => [x.type, x.value]));
  return `${p.year}-${p.month}-${p.day}`;
};
const sumaDies = (d, n) => new Date(Date.parse(d + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10);
// ── Fi de les eines comunes ──

// Executa l'acció demanada contra el Cookidoo amb el token (no surt mai a la resposta).
const c = $('Entrada i config').first().json;
const token = $input.first().json.token;
const { accio } = c;
const dades = c.dades || {};
const B = c.base.replace(/\/$/, '');
const L = c.idioma;
const sd = $getWorkflowStaticData('global');
const LLEGUM = /lentej|garbanz|alubi|jud[ií]a|frijol|guisante|soja|soya|tofu|tempeh|edamame|cacahuet|\bman[ií]\b|\bhaba|altramuz|azuki|hummus|\bmiso\b|tirabeque|garrof|fagiol|pisell/i;
const LLEGUM_EXTRA = /man[ií](?![a-záéíóúñ])/i; // «maní» amb accent, que el \b no detecta

async function api(method, path, { body, accept, query } = {}) {
  const url = `${B}/${path}` + (query ? `?${qs(query)}` : '');
  const r = await H.httpRequest({
    method, url,
    headers: {
      Authorization: 'Bearer ' + token,
      Accept: accept || 'application/json',
      'Accept-Language': L,
      'User-Agent': c.userAgent,
      ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
    },
    body: body !== undefined ? JSON.stringify(body) : undefined,
    returnFullResponse: true, ignoreHttpStatusErrors: true, encoding: 'text',
  });
  if (r.statusCode === 401) {
    delete sd.cookidoo;
    throw new Error('El Cookidoo ha rebutjat el token. L\'he esborrat: torna-ho a provar i farà login de nou.');
  }
  if (r.statusCode >= 400) throw new Error(`${method} ${path} → HTTP ${r.statusCode}: ${comATexte(r.body).slice(0, 300)}`);
  return comAJson(r.body);
}

const quantitat = (q) => {
  if (!q) return '';
  if (q.value != null) return String(q.value);
  if (q.from != null && q.to != null) return `${q.from}-${q.to}`;
  return q.from != null ? String(q.from) : '';
};
const ingredientText = (x) => [quantitat(x.quantity), x.unitNotation || '', x.ingredientNotation || '']
  .filter(Boolean).join(' ').trim() + (x.preparation ? `, ${x.preparation}` : '');
const minuts = (v) => (v == null ? null : v > 300 ? Math.round(v / 60) : v); // l'API dona segons
const decodeHtml = (s) => String(s).replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');

async function recepta(id, ambVariants) {
  const out = { id };
  try {
    const j = await api('GET', `recipes/recipe/${L}/${id}`);
    if (j && typeof j === 'object' && Array.isArray(j.recipeIngredientGroups)) {
      out.titol = j.title;
      if (j.servingSize) out.racions = `${quantitat(j.servingSize.quantity)} ${j.servingSize.unitNotation || ''}`.trim();
      const tt = (j.times || []).find((t) => t.type === 'totalTime');
      out.tempsTotalMin = tt && tt.quantity ? minuts(tt.quantity.value) : null;
      out.ingredients = j.recipeIngredientGroups.flatMap((g) => (g.recipeIngredients || []).map(ingredientText));
      out.colleccions = (j.inCollections || []).map((x) => x.title);
    }
  } catch (e) {
    out.avis = 'API de recepta: ' + e.message;
  }
  if (!out.ingredients || ambVariants) {
    try {
      const html = comATexte(await api('GET', `recipes/recipe/${L}/${id}`, { accept: 'text/html' }));
      if (!out.ingredients) {
        for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
          try {
            const ld = JSON.parse(m[1]);
            const r = [].concat(ld['@graph'] || ld).find((x) => x && x['@type'] === 'Recipe');
            if (r) {
              out.titol = out.titol || r.name;
              out.racions = out.racions || r.recipeYield;
              out.tempsTotal = r.totalTime;
              out.ingredients = r.recipeIngredient || [];
              break;
            }
          } catch (e) { /* següent bloc */ }
        }
      }
      if (ambVariants) {
        const i = html.indexOf('rdp-serving-size__variants-section');
        const tros = i >= 0 ? html.slice(i, i + 4000) : '';
        const ids = [...tros.matchAll(/\/recipes\/recipe\/[a-z]{2}-[A-Z]{2}\/(r\d+)/g)].map((m) => m[1]).filter((x) => x !== id);
        out.variants = [...new Set(ids)];
      }
      if (!out.titol) {
        const t = html.match(/<title>([^<]*)<\/title>/i);
        if (t) out.titol = decodeHtml(t[1]).trim();
      }
    } catch (e) {
      out.avis = (out.avis ? out.avis + ' | ' : '') + 'Pàgina web: ' + e.message;
    }
  }
  const text = (out.ingredients || []).join(' | ');
  const trobats = (out.ingredients || []).filter((x) => LLEGUM.test(x) || LLEGUM_EXTRA.test(x));
  out.llegum = trobats.length ? trobats : false;
  if (!text) out.llegum = 'no ho sé: no he pogut llegir els ingredients';
  return out;
}

async function colleccions(tipus) {
  const ruta = tipus === 'oficials' ? `organize/${L}/api/managed-list` : `organize/${L}/api/custom-list`;
  const accept = tipus === 'oficials'
    ? 'application/vnd.vorwerk.organize.managed-list.mobile+json'
    : 'application/vnd.vorwerk.organize.custom-list.mobile+json';
  const totes = [];
  for (let p = 0; p < 30; p++) {
    const r = await api('GET', ruta, { accept, query: { page: p } });
    const llistes = (r && (r.customlists || r.managedlists || r.managedLists)) || [];
    for (const l of llistes) {
      totes.push({
        id: l.id,
        titol: l.title,
        receptes: (l.chapters || []).flatMap((ch) => (ch.recipes || []).map((x) => ({ id: x.id, titol: x.title, tempsTotalMin: minuts(x.totalTime) }))),
      });
    }
    const pages = r && r.page && r.page.totalPages;
    if (!pages || p + 1 >= pages || !llistes.length) break;
  }
  return totes;
}

let resultat;
try {
  switch (accio) {
    case 'prova': {
      const d = avuiMadrid();
      const r = await api('GET', `planning/${L}/api/my-week/${d}`);
      resultat = { missatge: 'Login i lectura de «Mi semana» correctes.', dies: ((r && r.myDays) || []).map((x) => ({ dia: x.dayKey, receptes: (x.recipes || []).length })) };
      break;
    }
    case 'setmana_llegir': {
      const d0 = dades.data || avuiMadrid();
      const fi = sumaDies(d0, Number(dades.dies) || 7);
      const dies = {};
      for (const d of [d0, sumaDies(d0, 4)]) {
        const r = await api('GET', `planning/${L}/api/my-week/${d}`);
        for (const x of (r && r.myDays) || []) {
          if (x.dayKey < d0 || x.dayKey >= fi) continue;
          dies[x.dayKey] = {
            dia: x.dayKey,
            receptes: (x.recipes || []).map((y) => ({ id: y.id, titol: y.title })),
            ...(x.customerRecipeIds && x.customerRecipeIds.length ? { receptesPropies: x.customerRecipeIds } : {}),
          };
        }
      }
      resultat = Object.values(dies).sort((a, b) => a.dia.localeCompare(b.dia));
      break;
    }
    case 'setmana_afegir': {
      const fets = [];
      for (const e of dades.entrades || []) {
        const ids = e.receptes || (e.recepta ? [e.recepta] : []);
        if (!/^\d{4}-\d{2}-\d{2}$/.test(e.dia || '') || !ids.length) { fets.push({ ...e, ok: false, error: 'Falta el dia (AAAA-MM-DD) o la recepta.' }); continue; }
        const r = await api('PUT', `planning/${L}/api/my-day`, { body: { recipeIds: ids, dayKey: e.dia } });
        fets.push({ dia: e.dia, afegides: ids, ok: true, araAlDia: ((r && r.content && r.content.recipes) || []).map((x) => x.id) });
      }
      resultat = fets;
      break;
    }
    case 'setmana_treure': {
      const fets = [];
      for (const e of dades.entrades || []) {
        if (!/^\d{4}-\d{2}-\d{2}$/.test(e.dia || '') || !e.recepta) { fets.push({ ...e, ok: false, error: 'Falta el dia o la recepta.' }); continue; }
        await api('DELETE', `planning/${L}/api/my-day/${e.dia}/recipes/${e.recepta}`);
        fets.push({ dia: e.dia, treta: e.recepta, ok: true });
      }
      resultat = fets;
      break;
    }
    case 'receptes': {
      const ids = (dades.ids || []).slice(0, 40);
      resultat = [];
      for (const id of ids) resultat.push(await recepta(id, !!dades.variants));
      break;
    }
    case 'colleccions': {
      let llistes = await colleccions(dades.tipus === 'oficials' ? 'oficials' : 'meves');
      if (dades.nom) {
        const n = String(dades.nom).toLowerCase();
        llistes = llistes.filter((l) => String(l.titol).toLowerCase().includes(n));
      }
      if (dades.nomesNoms) llistes = llistes.map((l) => ({ id: l.id, titol: l.titol, nombre: l.receptes.length }));
      resultat = llistes;
      break;
    }
    case 'cercar': {
      const r = await api('GET', `search/${L}`, { query: { query: dades.text || '', page: dades.pagina, pageSize: dades.mida || 20 } });
      const hits = (r && (r.data || r.recipes)) || [];
      resultat = { total: r && r.total, receptes: hits.map((x) => ({ id: x.id, titol: x.title || x.name })) };
      break;
    }
    case 'llista_llegir': {
      const r = (await api('GET', `shopping/${L}`)) || {};
      resultat = {
        receptes: [...(r.recipes || []), ...(r.customerRecipes || [])].map((x) => ({ id: x.id, titol: x.title })),
        ingredients: [...(r.recipes || []), ...(r.customerRecipes || [])].flatMap((x) => (x.recipeIngredientGroups || []).map((i) => ({ id: i.id, text: ingredientText(i), tinc: !!i.isOwned }))),
        articles: (r.additionalItems || []).map((x) => ({ id: x.id, nom: x.name, tinc: !!x.isOwned })),
      };
      break;
    }
    case 'llista_afegir': {
      const articles = (dades.articles || []).map((x) => String(x).trim()).filter(Boolean);
      if (!articles.length) throw new Error('Falta «articles» (llista de textos).');
      const r = await api('POST', `shopping/${L}/additional-items/add`, { body: { itemsValue: articles } });
      resultat = { afegits: ((r && r.data) || []).map((x) => ({ id: x.id, nom: x.name })) };
      break;
    }
    case 'llista_treure': {
      const ids = dades.ids || [];
      if (!ids.length) throw new Error('Falta «ids» (els id dels articles a treure).');
      await api('POST', `shopping/${L}/additional-items/remove`, { body: { additionalItemIDs: ids } });
      resultat = { trets: ids };
      break;
    }
    case 'llista_buidar': {
      if (dades.confirmo !== true) throw new Error('Per buidar tota la llista cal "confirmo": true a «dades».');
      await api('DELETE', `shopping/${L}`);
      resultat = { buidada: true };
      break;
    }
    default:
      throw new Error(`Acció desconeguda: «${accio}». Vàlides: setmana_llegir, setmana_afegir, setmana_treure, receptes, colleccions, cercar, llista_llegir, llista_afegir, llista_treure, llista_buidar.`);
  }
  return [{ json: { ok: true, accio, resultat } }];
} catch (e) {
  return [{ json: { ok: false, accio, error: e.message } }];
}
